import{_ as t,o as a,c as i,a4 as s}from"./chunks/framework.DCsBdTIw.js";const u=JSON.parse('{"title":"Impact Program","description":"Tokeness offers 10 million to 5 billion tokens per month of AI API support for open-source projects, public-interest projects, and social enterprises.","frontmatter":{"title":"Impact Program","description":"Tokeness offers 10 million to 5 billion tokens per month of AI API support for open-source projects, public-interest projects, and social enterprises."},"headers":[],"relativePath":"partners/impact.md","filePath":"partners/impact.md","lastUpdated":1784332800000}'),o={name:"partners/impact.md"};function r(n,e,l,p,d,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="impact-program" tabindex="-1">Impact Program <a class="header-anchor" href="#impact-program" aria-label="Permalink to &quot;Impact Program&quot;">​</a></h1><p>Tokeness runs an impact program for open-source projects, public-interest projects, and social enterprises. Selected projects receive <code>10 million – 5 billion</code> tokens of AI API support per month for development, operations, knowledge services, content production, automated processing, and public service scenarios.</p><p>Impact quota is calculated using <code>MiMo-V2.5</code> as the baseline model. Projects may use other models; actual consumption is converted according to the Tokeness platform model price, model permissions, and equivalent quota rules.</p><h2 id="eligible-projects" tabindex="-1">Eligible Projects <a class="header-anchor" href="#eligible-projects" aria-label="Permalink to &quot;Eligible Projects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Open-source projects</td><td>Open-source projects in developer tools, infrastructure, educational resources, accessibility technology, public data, AI safety, and similar areas</td></tr><tr><td>Public-interest projects</td><td>Public-interest organizations or initiatives in education, healthcare, environmental protection, disaster response, mental health, rural services, vulnerable group support, and similar fields</td></tr><tr><td>Social enterprises</td><td>Enterprises that solve social problems through commercial means, such as inclusive education, employment for people with disabilities, sustainable consumption, community services, and public-interest technology</td></tr></tbody></table><h2 id="quota-tiers" tabindex="-1">Quota Tiers <a class="header-anchor" href="#quota-tiers" aria-label="Permalink to &quot;Quota Tiers&quot;">​</a></h2><p>Impact quota is issued monthly. It cannot be cashed out, refunded, or resold. Unused quota does not roll over by default.</p><table tabindex="0"><thead><tr><th>Tier</th><th style="text-align:right;">Monthly baseline quota</th><th>Suitable for</th></tr></thead><tbody><tr><td>Starter</td><td style="text-align:right;">10 million tokens</td><td>Early-stage projects with a website homepage, public repository, or project release page</td></tr><tr><td>Builder</td><td style="text-align:right;">50 million tokens</td><td>Projects with real users, a community, or beneficiaries</td></tr><tr><td>Growth</td><td style="text-align:right;">100 million tokens</td><td>Projects with stable use cases and quantifiable impact goals</td></tr><tr><td>Impact</td><td style="text-align:right;">500 million tokens</td><td>Projects serving a large scale with mature operational mechanisms</td></tr><tr><td>Strategic</td><td style="text-align:right;">5 billion tokens</td><td>High-impact infrastructure, key public-interest platforms, or joint projects</td></tr></tbody></table><p>The <code>Strategic</code> tier requires a separate review. Quota must be released in batches — weekly, per key, or per project — and is subject to weekly or monthly review. If a review is not passed, Tokeness may lower the tier, suspend further releases, or adjust the model scope.</p><h2 id="pre-application-requirements" tabindex="-1">Pre-application Requirements <a class="header-anchor" href="#pre-application-requirements" aria-label="Permalink to &quot;Pre-application Requirements&quot;">​</a></h2><p>Before applying, the project must add a Tokeness support statement in a designated public location. Projects that have not added the statement, have placed it in an incorrect location, or cannot be publicly accessed will not enter the quota review process.</p><p>The placement location depends on the project&#39;s public presence:</p><table tabindex="0"><thead><tr><th>Location</th><th>Example</th></tr></thead><tbody><tr><td>Public repository</td><td><code>README.md</code> in a GitHub, Gitee, CNB, or similar repository</td></tr><tr><td>Project website</td><td>Must be displayed on the homepage; placing it in the homepage footer is recommended</td></tr><tr><td>No website and no public repository</td><td>Bottom of the project release page, end of project updates, end of a blog post, or end of a public account article</td></tr></tbody></table><p>If the project has both a website and a public repository, the homepage footer or the repository <code>README.md</code> takes priority. Sponsor pages, partner pages, documentation pages, secondary pages, or temporary announcements cannot replace the homepage footer or repository <code>README.md</code>.</p><p>Recommended wording for a repository <code>README.md</code>:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;p&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  The AI API support for this project is sponsored by</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;a href=&quot;https://tokeness.ai&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Tokeness.ai</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/a&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/p&gt;</span></span></code></pre></div><p>Wording for a website footer or release page bottom:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The AI API support for this project is sponsored by</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://tokeness.ai&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;_blank&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;noopener&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://docs.tokeness.ai/logo.svg&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> alt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Tokeness&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;24&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Tokeness.ai</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Tokeness will check whether the link is still publicly accessible during both the application review and renewal review. Failure to display the logo, failure to link to <code>https://tokeness.ai</code>, or placing the link in an incorrect location will all be treated as not meeting the pre-application requirements.</p><h2 id="available-capabilities" tabindex="-1">Available Capabilities <a class="header-anchor" href="#available-capabilities" aria-label="Permalink to &quot;Available Capabilities&quot;">​</a></h2><p>Selected projects will receive one or more impact-specific API keys. Tokeness will configure the quota, model scope, group, and necessary restriction policies based on the project&#39;s use case.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td>OpenAI-compatible endpoint</td><td>Use <code>https://n.tokeness.dev/v1</code> to connect most tools that support a custom base URL</td></tr><tr><td>Multi-model access</td><td><code>DeepSeek-V4-Flash</code> is the default quota baseline; other models may be used according to the rules</td></tr><tr><td>Key and quota control</td><td>Split keys by project, environment, or task, and set quota limits</td></tr><tr><td>Usage logs</td><td>Verify requests, models, status, and consumption in the console</td></tr><tr><td>Data dashboard</td><td>Observe model call trends and monthly consumption</td></tr></tbody></table><h2 id="typical-scenarios" tabindex="-1">Typical Scenarios <a class="header-anchor" href="#typical-scenarios" aria-label="Permalink to &quot;Typical Scenarios&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Project type</th><th>Recommended scenarios</th></tr></thead><tbody><tr><td>Open-source projects</td><td>Issue classification, PR review assistance, documentation generation, test case generation, multilingual translation, contributor Q&amp;A</td></tr><tr><td>Public-interest projects</td><td>Volunteer training, policy Q&amp;A, beneficiary consultation, material organization, accessibility content rewriting</td></tr><tr><td>Social enterprises</td><td>User support, knowledge base Q&amp;A, educational practice, operations automation, report generation</td></tr></tbody></table><p>High-cost models, image generation, long context, high-concurrency batch processing, and similar scenarios may require a separate explanation of the use case and may be subject to finer model scope and quota limits.</p><h2 id="application-process" tabindex="-1">Application Process <a class="header-anchor" href="#application-process" aria-label="Permalink to &quot;Application Process&quot;">​</a></h2><ol><li>Add a Tokeness support statement in the repository <code>README.md</code>, the website homepage footer, or — if there is no website and no public repository — at the bottom of the project release page, the end of project updates, the end of a blog post, or the end of a public account article.</li><li>Prepare a project introduction, public links, use cases, estimated monthly token demand, and impact goals.</li><li>Send the application materials to <a href="mailto:contact@tokeness.ai" target="_blank" rel="noreferrer">contact@tokeness.ai</a>. The email subject should be <code>Impact Program Application - Project Name</code>.</li><li>Tokeness reviews the project&#39;s authenticity, public acknowledgment link, quota needs, and compliance risks.</li><li>After approval, the project registers or confirms a Tokeness account.</li><li>Tokeness issues the impact-specific key and configures the quota, model scope, and usage limits.</li><li>The project submits a brief monthly usage report. Tokeness decides on renewal, tier upgrade, tier downgrade, or discontinuation based on usage.</li></ol><h2 id="review-criteria" tabindex="-1">Review Criteria <a class="header-anchor" href="#review-criteria" aria-label="Permalink to &quot;Review Criteria&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th style="text-align:right;">Weight</th></tr></thead><tbody><tr><td>Public value and social impact</td><td style="text-align:right;">30%</td></tr><tr><td>Project authenticity and operational sustainability</td><td style="text-align:right;">25%</td></tr><tr><td>Clarity of AI use cases</td><td style="text-align:right;">20%</td></tr><tr><td>Reasonableness of quota needs</td><td style="text-align:right;">15%</td></tr><tr><td>Openness, transparency, or reusable value</td><td style="text-align:right;">10%</td></tr></tbody></table><p>Tokeness prioritizes projects that already have real users, beneficiaries, communities, repository records, or public service cases.</p><h2 id="usage-rules" tabindex="-1">Usage Rules <a class="header-anchor" href="#usage-rules" aria-label="Permalink to &quot;Usage Rules&quot;">​</a></h2><p>Impact quota may only be used for the open-source, public-interest, or social value scenarios described in the application.</p><p>Prohibited behaviors include:</p><ul><li>Selling, subleasing, or gifting impact quota or API keys.</li><li>Using impact keys for commercial distribution, proxy forwarding, or unrelated projects.</li><li>Illegal activities, infringement, fraud, attacks, risk-control circumvention, or spam content production.</li><li>Malicious consumption, abnormal high concurrency, uncontrolled retries, or calls that clearly deviate from the stated use case.</li><li>Embedding API keys in frontend code, public repositories, screenshots, group chats, or other insecure locations.</li></ul><p>In the event of abnormal requests, major risks, upstream policy changes, prolonged lack of feedback, or an invalid public acknowledgment link, Tokeness may suspend, rate-limit, adjust the model scope, stop further quota, or revoke impact eligibility.</p><h2 id="renewal-and-feedback" tabindex="-1">Renewal and Feedback <a class="header-anchor" href="#renewal-and-feedback" aria-label="Permalink to &quot;Renewal and Feedback&quot;">​</a></h2><p>Impact support is reviewed monthly by default. Projects must maintain the public acknowledgment link and submit monthly feedback:</p><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td>Usage</td><td>Main use cases this month, call volume, and model types</td></tr><tr><td>Impact results</td><td>People served, tasks processed, time saved, community contributions, or other measurable outcomes</td></tr><tr><td>Next month&#39;s plan</td><td>Estimated quota, model needs, and new use cases</td></tr></tbody></table><p>Projects with sufficient feedback, clear impact, and compliant usage may apply for a tier upgrade. Projects with prolonged inactivity, no feedback, or unclear purpose may have their tier lowered or support discontinued.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Application and cooperation inquiries: <a href="mailto:contact@tokeness.ai" target="_blank" rel="noreferrer">contact@tokeness.ai</a></p><p>Service portal: <a href="https://tokeness.ai" target="_blank" rel="noreferrer">tokeness.ai</a></p>`,42)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
